// El sitio manda el pedido y el mensaje ya armado (src/lib/whatsapp.ts →
// buildOrderMessage). Acá solo se valida el origen y se reenvía a Evolution.
const input = $input.first().json;
const d = input.body ?? input;

// Solo el sitio conoce este secreto (N8N_WEBHOOK_SECRET en el sitio,
// MKPETS_WEBHOOK_SECRET en n8n). Sin esto, cualquiera que descubra la URL del
// webhook podría mandar WhatsApps desde el número de la tienda.
const expected = $env.MKPETS_WEBHOOK_SECRET;
const received = (input.headers || {})['x-mkpets-secret'];
if (expected && received !== expected) {
  return [];
}

if (!d.phone || !d.message) {
  return [];
}

return [{ json: { phone: String(d.phone), message: String(d.message), image: d.image || null } }];
